def create_entities(entities, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # --- request log / rate limiting (best-effort, offline) ---
    def _log(status, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "create_entities",
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now_iso,
            }
        )
        _save("request_logs.json", logs)

    def _rate_limited():
        # Simple local limit: 120 writes / rolling minute, 5000 writes / day
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff_min = (now - datetime.timedelta(seconds=60)).isoformat()
        cutoff_day = (now - datetime.timedelta(days=1)).isoformat()
        recent = 0
        day = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            if ts >= cutoff_min and r.get("endpoint") in ("create_entities", "create_relations", "add_observations", "delete_entities"):
                if str(r.get("status", "")).startswith("2"):
                    recent += 1
            if ts >= cutoff_day and r.get("endpoint") in ("create_entities", "create_relations", "add_observations", "delete_entities"):
                if str(r.get("status", "")).startswith("2"):
                    day += 1
        if recent >= 120:
            return "RATE_LIMIT"
        if day >= 5000:
            return "QUOTA_EXCEEDED"
        return False

    rl = _rate_limited()
    if rl:
        code = "RATE_LIMIT" if rl == "RATE_LIMIT" else "QUOTA_EXCEEDED"
        _log("429", code)
        return _err(code, "Write quota exceeded." if code == "QUOTA_EXCEEDED" else "Rate limit exceeded.")

    # --- validation ---
    if not isinstance(entities, list):
        _log("400", "entities must be an array")
        return _err("VALIDATION_ERROR", "entities must be an array.")
    for i, e in enumerate(entities):
        if not isinstance(e, dict):
            _log("400", f"entities[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"entities[{i}] must be an object.")
        allowed = {"name", "entity_type", "summary", "properties", "confidence"}
        unknown = set(e.keys()) - allowed
        if unknown:
            _log("400", f"entities[{i}] contains unknown fields")
            return _err("VALIDATION_ERROR", f"entities[{i}] contains unknown fields.", unknown_fields=sorted(list(unknown)))
        if "name" not in e or "entity_type" not in e:
            _log("400", f"entities[{i}] missing required fields")
            return _err("VALIDATION_ERROR", f"entities[{i}] is missing required fields 'name' and/or 'entity_type'.")
        if not isinstance(e.get("name"), str) or not e["name"].strip():
            _log("400", f"entities[{i}].name invalid")
            return _err("VALIDATION_ERROR", f"entities[{i}].name must be a non-empty string.")
        if not isinstance(e.get("entity_type"), str) or not e["entity_type"].strip():
            _log("400", f"entities[{i}].entity_type invalid")
            return _err("VALIDATION_ERROR", f"entities[{i}].entity_type must be a non-empty string.")
        if "summary" in e and e["summary"] is not None and not isinstance(e["summary"], str):
            _log("400", f"entities[{i}].summary invalid")
            return _err("VALIDATION_ERROR", f"entities[{i}].summary must be a string or null.")
        if "properties" in e and e["properties"] is not None and not isinstance(e["properties"], dict):
            _log("400", f"entities[{i}].properties invalid")
            return _err("VALIDATION_ERROR", f"entities[{i}].properties must be an object.")
        if "confidence" in e and e["confidence"] is not None:
            if not isinstance(e["confidence"], (int, float)) or isinstance(e["confidence"], bool):
                _log("400", f"entities[{i}].confidence invalid type")
                return _err("VALIDATION_ERROR", f"entities[{i}].confidence must be a number.")
            if e["confidence"] < 0 or e["confidence"] > 1:
                _log("400", f"entities[{i}].confidence out of range")
                return _err("VALIDATION_ERROR", f"entities[{i}].confidence must be between 0 and 1.")

    # --- mutate (upsert by case-insensitive name among active) ---
    ents = _load("entities.json")
    if not isinstance(ents, list):
        ents = []
    events = _load("graph_events.json")
    if not isinstance(events, list):
        events = []

    active_by_lower = {}
    for row in ents:
        if isinstance(row, dict) and row.get("status") == "active" and isinstance(row.get("name"), str):
            active_by_lower[row["name"].strip().lower()] = row

    def _new_id(prefix, rows):
        # ULID-like crockford base32 timestamp+entropy
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(now.timestamp() * 1000)

        def enc_base32(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n & 31])
                n >>= 5
            return "".join(reversed(out))

        # 10 chars time (50 bits) + 16 chars entropy ~ ULID-ish
        time_part = enc_base32(ms & ((1 << 50) - 1), 10)
        # deterministic-ish entropy from current length + sha
        h = hashlib.sha256(f"{prefix}|{now_iso}|{len(rows)}".encode("utf-8")).digest()
        ent = int.from_bytes(h[:10], "big")  # 80 bits
        ent_part = enc_base32(ent, 16)
        return f"{prefix}_{time_part}{ent_part}"

    created_or_updated = []
    for e in entities:
        name = e["name"].strip()
        lname = name.lower()
        existing = active_by_lower.get(lname)

        # defaults
        summary = e.get("summary", None)
        props = e.get("properties", None)
        if props is None:
            props = {}
        conf = e.get("confidence", None)
        if conf is None:
            conf = 1.0

        if existing:
            before = dict(existing)
            existing["name"] = name  # preserve canonical casing from latest write
            existing["entity_type"] = e["entity_type"].strip()
            existing["summary"] = summary
            existing["properties"] = props
            existing["confidence"] = float(conf)
            existing["confidence_updated_at"] = now_iso
            existing["updated_at"] = now_iso
            # constraints: deleted_at must be null for active
            existing["status"] = "active"
            existing["deleted_at"] = None

            after = dict(existing)
            ev = {
                "id": _new_id("mmt_evt", events),
                "event_type": "entity.updated",
                "entity_id": existing["id"],
                "relation_id": None,
                "observation_id": None,
                "embedding_id": None,
                "actor": {"tool": "create_entities"},
                "payload": {"before": before, "after": after},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            events.append(ev)
            created_or_updated.append(existing)
        else:
            # enforce unique(lower(name)) among active: checked above
            new_row = {
                "id": _new_id("mmt_ent", ents),
                "name": name,
                "entity_type": e["entity_type"].strip(),
                "summary": summary,
                "properties": props,
                "confidence": float(conf),
                "confidence_updated_at": now_iso,
                "deleted_at": None,
                "status": "active",
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            ents.append(new_row)
            active_by_lower[lname] = new_row

            ev = {
                "id": _new_id("mmt_evt", events),
                "event_type": "entity.created",
                "entity_id": new_row["id"],
                "relation_id": None,
                "observation_id": None,
                "embedding_id": None,
                "actor": {"tool": "create_entities"},
                "payload": {"snapshot": dict(new_row)},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            events.append(ev)
            created_or_updated.append(new_row)

    _save("entities.json", ents)
    _save("graph_events.json", events)
    _log("200", f"upserted={len(created_or_updated)}")
    return {"entities": created_or_updated, "count": len(created_or_updated)}

def create_relations(relations, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # request logging + quota/rate limiting via request_logs.json (may not exist yet)
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load_logs()
        logs.append({
            "id": f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "create_relations",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
            "created_at": now_iso,
        })
        _save_logs(logs)

    def _enforce_limits():
        # Rolling limits on successful write endpoints
        logs = _load_logs()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        mut_eps = {
            "create_entities", "create_relations", "add_observations",
            "delete_entities", "delete_relations", "delete_observations", "update_relation"
        }

        recent_ok = 0
        daily_ok = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in mut_eps:
                continue
            st = str(r.get("status", ""))
            if not (st.startswith("2") or st in ("ok", "success", "200", "201", "204")):
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_ok += 1
            if ts >= day_ago:
                daily_ok += 1

        # 60 successful writes per minute; 10k per day
        if recent_ok >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded: too many successful write requests in the last minute.")
        if daily_ok >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("429", limit_err["error"]["code"])
        return limit_err

    # validation
    if not isinstance(relations, list):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "relations must be an array.")
    if len(relations) == 0:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "relations must not be empty.")

    ent_pat = re.compile(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{10,}$")
    for i, r in enumerate(relations):
        if not isinstance(r, dict):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}] must be an object.")
        allowed = {"from_entity_id", "to_entity_id", "predicate", "properties", "confidence"}
        unknown = set(r.keys()) - allowed
        if unknown:
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}] contains unknown fields: {sorted(unknown)}")
        for req in ("from_entity_id", "to_entity_id", "predicate"):
            if req not in r:
                _log("400", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"relations[{i}] missing required field '{req}'.")
        fe = r.get("from_entity_id")
        te = r.get("to_entity_id")
        if not isinstance(fe, str) or not ent_pat.match(fe):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}].from_entity_id must match ^mmt_ent_[0-9A-HJKMNP-TV-Z]{{10,}}$")
        if not isinstance(te, str) or not ent_pat.match(te):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}].to_entity_id must match ^mmt_ent_[0-9A-HJKMNP-TV-Z]{{10,}}$")
        # IMPORTANT: a real request with self-relations should be rejected (business rule constraint)
        if fe == te:
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "relations[0] violates constraint from_entity_id <> to_entity_id (self-relations are not allowed).")
        pred = r.get("predicate")
        if not isinstance(pred, str):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}].predicate must be a string.")
        if pred.strip() == "":
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}] violates constraint predicate <> '' (predicate must be non-empty).")
        if "properties" in r and r["properties"] is not None and not isinstance(r["properties"], dict):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"relations[{i}].properties must be an object.")
        if "confidence" in r and r["confidence"] is not None:
            c = r["confidence"]
            if not isinstance(c, (int, float)) or isinstance(c, bool):
                _log("400", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"relations[{i}].confidence must be a number.")
            if c < 0 or c > 1:
                _log("400", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"relations[{i}] violates constraint confidence >= 0 and confidence <= 1.")

    entities = _load("entities.json")
    relations_rows = _load("relations.json")
    events = _load("graph_events.json")
    if not isinstance(entities, list):
        entities = []
    if not isinstance(relations_rows, list):
        relations_rows = []
    if not isinstance(events, list):
        events = []

    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and isinstance(e.get("id"), str)}
    # FK checks for active entities only
    for i, r in enumerate(relations):
        fe = r["from_entity_id"]
        te = r["to_entity_id"]
        fe_row = ent_by_id.get(fe)
        te_row = ent_by_id.get(te)
        if not fe_row or not te_row:
            _log("404", "NOT_FOUND")
            return _err("NOT_FOUND", f"relations[{i}] references unknown entity id(s).", missing_entity_ids=[x for x in [fe, te] if x not in ent_by_id])
        if fe_row.get("status") != "active" or te_row.get("status") != "active":
            _log("409", "CONFLICT")
            return _err("CONFLICT", f"relations[{i}] requires from_entity_id and to_entity_id to reference active entities.")

    # detect duplicates; per rules: attempts must either update_relation or be rejected.
    # We'll reject with CONFLICT and point to the rule.
    active_key_to_rel = {}
    for rel in relations_rows:
        if not isinstance(rel, dict):
            continue
        if rel.get("status") != "active":
            continue
        key = (rel.get("from_entity_id"), rel.get("to_entity_id"), str(rel.get("predicate", "")).strip().lower())
        active_key_to_rel[key] = rel

    for i, r in enumerate(relations):
        key = (r["from_entity_id"], r["to_entity_id"], str(r["predicate"]).strip().lower())
        if key in active_key_to_rel:
            _log("409", "CONFLICT")
            return _err("CONFLICT", f"relations[{i}] violates constraint unique(from_entity_id, to_entity_id, lower(predicate)) where status='active' (duplicate active relation).")

    def _new_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # time component in ms
        ms = int(time.time() * 1000)
        t_part = ""
        x = ms
        for _ in range(10):
            t_part = alphabet[x % 32] + t_part
            x //= 32
        import random
        rand_part = "".join(random.choice(alphabet) for _ in range(16))
        rid = f"{prefix}{t_part}{rand_part}"
        if rid in existing_ids:
            # extremely unlikely; try again once
            rand_part = "".join(random.choice(alphabet) for _ in range(16))
            rid = f"{prefix}{t_part}{rand_part}"
        return rid

    existing_rel_ids = {r.get("id") for r in relations_rows if isinstance(r, dict)}
    existing_evt_ids = {e.get("id") for e in events if isinstance(e, dict)}

    created = []
    for r in relations:
        pred_norm = str(r["predicate"]).strip()
        props = r.get("properties")
        if props is None:
            props = {}
        conf = r.get("confidence")
        if conf is None:
            conf = 0.5

        rel_id = _new_id("mmt_rel_", existing_rel_ids)
        existing_rel_ids.add(rel_id)

        rel_row = {
            "id": rel_id,
            "from_entity_id": r["from_entity_id"],
            "to_entity_id": r["to_entity_id"],
            "predicate": pred_norm,
            "properties": props,
            "confidence": float(conf),
            "confidence_updated_at": None,
            "status": "active",
            "deleted_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        relations_rows.append(rel_row)
        created.append(rel_row)

        evt_id = _new_id("mmt_evt_", existing_evt_ids)
        existing_evt_ids.add(evt_id)
        events.append({
            "id": evt_id,
            "event_type": "relation.created",
            "entity_id": None,
            "relation_id": rel_id,
            "observation_id": None,
            "embedding_id": None,
            "actor": {"tool": "create_relations"},
            "payload": {"relation": dict(rel_row)},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    _save("relations.json", relations_rows)
    _save("graph_events.json", events)

    _log("201")
    return {
        "relations": created,
        "count": len(created),
        "created_at": now_iso,
    }

def add_observations(observations, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(status, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "add_observations",
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now_iso,
            }
        )
        _save("request_logs.json", logs)

    def _rate_limited():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff_min = (now - datetime.timedelta(seconds=60)).isoformat()
        cutoff_day = (now - datetime.timedelta(days=1)).isoformat()
        recent = 0
        day = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            if ts >= cutoff_min and r.get("endpoint") in ("create_entities", "create_relations", "add_observations", "delete_entities"):
                if str(r.get("status", "")).startswith("2"):
                    recent += 1
            if ts >= cutoff_day and r.get("endpoint") in ("create_entities", "create_relations", "add_observations", "delete_entities"):
                if str(r.get("status", "")).startswith("2"):
                    day += 1
        if recent >= 120:
            return "RATE_LIMIT"
        if day >= 5000:
            return "QUOTA_EXCEEDED"
        return False

    rl = _rate_limited()
    if rl:
        code = "RATE_LIMIT" if rl == "RATE_LIMIT" else "QUOTA_EXCEEDED"
        _log("429", code)
        return _err(code, "Write quota exceeded." if code == "QUOTA_EXCEEDED" else "Rate limit exceeded.")

    if not isinstance(observations, list):
        _log("400", "observations must be an array")
        return _err("VALIDATION_ERROR", "observations must be an array.")

    ent_pat = re.compile(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("observed_at must be a string")
        # Accept 'Z'
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None:
            # Require timezone; treat as validation error
            raise ValueError("observed_at must include timezone")
        return dt.astimezone(datetime.timezone.utc).isoformat()

    for i, o in enumerate(observations):
        if not isinstance(o, dict):
            _log("400", f"observations[{i}] must be object")
            return _err("VALIDATION_ERROR", f"observations[{i}] must be an object.")
        allowed = {"entity_id", "content", "source", "observed_at", "confidence"}
        unknown = set(o.keys()) - allowed
        if unknown:
            _log("400", f"observations[{i}] unknown fields")
            return _err("VALIDATION_ERROR", f"observations[{i}] contains unknown fields.", unknown_fields=sorted(list(unknown)))
        for req in ("entity_id", "content"):
            if req not in o:
                _log("400", f"observations[{i}] missing {req}")
                return _err("VALIDATION_ERROR", f"observations[{i}] is missing required field '{req}'.")
        if not isinstance(o["entity_id"], str) or not ent_pat.match(o["entity_id"]):
            _log("400", f"observations[{i}].entity_id invalid")
            return _err("VALIDATION_ERROR", f"observations[{i}].entity_id is invalid.")
        if not isinstance(o["content"], str) or not o["content"].strip():
            _log("400", f"observations[{i}].content invalid")
            return _err("VALIDATION_ERROR", f"observations[{i}].content must be a non-empty string.")
        if "source" in o and o["source"] is not None and not isinstance(o["source"], str):
            _log("400", f"observations[{i}].source invalid")
            return _err("VALIDATION_ERROR", f"observations[{i}].source must be a string or null.")
        if "observed_at" in o and o["observed_at"] is not None:
            try:
                _ = _parse_rfc3339(o["observed_at"])
            except ValueError as ve:
                _log("400", f"observations[{i}].observed_at invalid")
                return _err("VALIDATION_ERROR", f"observations[{i}].observed_at is invalid RFC3339 datetime.", detail=str(ve))
        if "confidence" in o and o["confidence"] is not None:
            if not isinstance(o["confidence"], (int, float)) or isinstance(o["confidence"], bool):
                _log("400", f"observations[{i}].confidence invalid type")
                return _err("VALIDATION_ERROR", f"observations[{i}].confidence must be a number.")
            if o["confidence"] < 0 or o["confidence"] > 1:
                _log("400", f"observations[{i}].confidence out of range")
                return _err("VALIDATION_ERROR", f"observations[{i}].confidence must be between 0 and 1.")

    ents = _load("entities.json")
    if not isinstance(ents, list):
        ents = []
    active_ent_ids = {e.get("id") for e in ents if isinstance(e, dict) and e.get("status") == "active"}

    for i, o in enumerate(observations):
        if o["entity_id"] not in active_ent_ids:
            _log("404", f"entity not found/active at {i}")
            return _err("NOT_FOUND", f"observations[{i}].entity_id does not reference an active entity.", entity_id=o["entity_id"])

    obs = _load("observations.json")
    if not isinstance(obs, list):
        obs = []
    events = _load("graph_events.json")
    if not isinstance(events, list):
        events = []

    def _new_id(prefix, rows):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(now.timestamp() * 1000)

        def enc_base32(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n & 31])
                n >>= 5
            return "".join(reversed(out))

        time_part = enc_base32(ms & ((1 << 50) - 1), 10)
        h = hashlib.sha256(f"{prefix}|{now_iso}|{len(rows)}".encode("utf-8")).digest()
        ent = int.from_bytes(h[:10], "big")
        ent_part = enc_base32(ent, 16)
        return f"{prefix}_{time_part}{ent_part}"

    created = []
    for o in observations:
        conf = o.get("confidence", None)
        if conf is None:
            conf = 1.0
        props_observed_at = None
        if "observed_at" in o and o["observed_at"] is not None:
            try:
                props_observed_at = _parse_rfc3339(o["observed_at"])
            except ValueError:
                _log("400", "observed_at invalid")
                return _err("VALIDATION_ERROR", "observed_at is invalid RFC3339 datetime.")

        row = {
            "id": _new_id("mmt_obs", obs),
            "entity_id": o["entity_id"],
            "content": o["content"].strip(),
            "source": o.get("source", None),
            "observed_at": props_observed_at,
            "confidence": float(conf),
            "status": "active",
            "deleted_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        obs.append(row)

        ev = {
            "id": _new_id("mmt_evt", events),
            "event_type": "observation.created",
            "entity_id": row["entity_id"],
            "relation_id": None,
            "observation_id": row["id"],
            "embedding_id": None,
            "actor": {"tool": "add_observations"},
            "payload": {"snapshot": dict(row)},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        events.append(ev)
        created.append(row)

    _save("observations.json", obs)
    _save("graph_events.json", events)
    _log("200", f"created={len(created)}")
    return {"observations": created, "count": len(created)}

def delete_entities(entity_ids, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(status, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{now.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "delete_entities",
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": now_iso,
            }
        )
        _save("request_logs.json", logs)

    def _rate_limited():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False
        cutoff_min = (now - datetime.timedelta(seconds=60)).isoformat()
        cutoff_day = (now - datetime.timedelta(days=1)).isoformat()
        recent = 0
        day = 0
        for r in logs:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            if ts >= cutoff_min and r.get("endpoint") in ("create_entities", "create_relations", "add_observations", "delete_entities"):
                if str(r.get("status", "")).startswith("2"):
                    recent += 1
            if ts >= cutoff_day and r.get("endpoint") in ("create_entities", "create_relations", "add_observations", "delete_entities"):
                if str(r.get("status", "")).startswith("2"):
                    day += 1
        if recent >= 120:
            return "RATE_LIMIT"
        if day >= 5000:
            return "QUOTA_EXCEEDED"
        return False

    rl = _rate_limited()
    if rl:
        code = "RATE_LIMIT" if rl == "RATE_LIMIT" else "QUOTA_EXCEEDED"
        _log("429", code)
        return _err(code, "Write quota exceeded." if code == "QUOTA_EXCEEDED" else "Rate limit exceeded.")

    ent_pat = re.compile(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{10,}$")

    if not isinstance(entity_ids, list) or len(entity_ids) < 1:
        _log("400", "entity_ids must be non-empty array")
        return _err("VALIDATION_ERROR", "entity_ids must be a non-empty array.")
    for i, eid in enumerate(entity_ids):
        if not isinstance(eid, str) or not ent_pat.match(eid):
            _log("400", f"invalid id at {i}")
            return _err("VALIDATION_ERROR", f"entity_ids[{i}] is invalid.")

    ents = _load("entities.json")
    if not isinstance(ents, list):
        ents = []
    rels = _load("relations.json")
    if not isinstance(rels, list):
        rels = []
    obs = _load("observations.json")
    if not isinstance(obs, list):
        obs = []
    events = _load("graph_events.json")
    if not isinstance(events, list):
        events = []

    by_id = {e.get("id"): e for e in ents if isinstance(e, dict) and isinstance(e.get("id"), str)}
    missing = [eid for eid in entity_ids if eid not in by_id]
    if missing:
        _log("404", "some entities not found")
        return _err("NOT_FOUND", "One or more entity_ids were not found.", missing_entity_ids=missing)

    def _new_id(prefix, rows):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(now.timestamp() * 1000)

        def enc_base32(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n & 31])
                n >>= 5
            return "".join(reversed(out))

        time_part = enc_base32(ms & ((1 << 50) - 1), 10)
        h = hashlib.sha256(f"{prefix}|{now_iso}|{len(rows)}".encode("utf-8")).digest()
        ent = int.from_bytes(h[:10], "big")
        ent_part = enc_base32(ent, 16)
        return f"{prefix}_{time_part}{ent_part}"

    to_delete = set(entity_ids)

    # soft delete entities (idempotent: if already deleted, keep as deleted)
    deleted_entities = 0
    for eid in entity_ids:
        e = by_id[eid]
        if e.get("status") == "active":
            before = dict(e)
            e["status"] = "deleted"
            e["deleted_at"] = now_iso
            e["updated_at"] = now_iso
            # constraint: deleted_at not null when deleted
            if e.get("deleted_at") is None:
                e["deleted_at"] = now_iso
            ev = {
                "id": _new_id("mmt_evt", events),
                "event_type": "entity.deleted",
                "entity_id": eid,
                "relation_id": None,
                "observation_id": None,
                "embedding_id": None,
                "actor": {"tool": "delete_entities"},
                "payload": {"before": before, "after": dict(e)},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            events.append(ev)
            deleted_entities += 1

    # cascade soft delete relations
    deleted_relations = 0
    for r in rels:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("from_entity_id") in to_delete or r.get("to_entity_id") in to_delete:
            before = dict(r)
            r["status"] = "deleted"
            r["deleted_at"] = now_iso
            r["updated_at"] = now_iso
            ev = {
                "id": _new_id("mmt_evt", events),
                "event_type": "relation.deleted",
                "entity_id": None,
                "relation_id": r.get("id"),
                "observation_id": None,
                "embedding_id": None,
                "actor": {"tool": "delete_entities"},
                "payload": {"before": before, "after": dict(r)},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            events.append(ev)
            deleted_relations += 1

    # cascade soft delete observations
    deleted_observations = 0
    for o in obs:
        if not isinstance(o, dict):
            continue
        if o.get("status") != "active":
            continue
        if o.get("entity_id") in to_delete:
            before = dict(o)
            o["status"] = "deleted"
            o["deleted_at"] = now_iso
            o["updated_at"] = now_iso
            ev = {
                "id": _new_id("mmt_evt", events),
                "event_type": "observation.deleted",
                "entity_id": o.get("entity_id"),
                "relation_id": None,
                "observation_id": o.get("id"),
                "embedding_id": None,
                "actor": {"tool": "delete_entities"},
                "payload": {"before": before, "after": dict(o)},
                "occurred_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            events.append(ev)
            deleted_observations += 1

    # NO SUCCESS WITHOUT EFFECT: if all requested were already deleted and nothing cascaded, return NOT_FOUND?
    # Realistic behavior: deleting already-deleted entities is an invalid transition (deleted->[]). Treat as idempotent delete.
    # However contract forbids "success with zero affected" for mutation matched no row; here rows matched.
    _save("entities.json", ents)
    _save("relations.json", rels)
    _save("observations.json", obs)
    _save("graph_events.json", events)

    _log("200", f"entities={deleted_entities}, relations={deleted_relations}, observations={deleted_observations}")
    return {
        "deleted": {
            "entity_ids": list(entity_ids),
            "entities_deleted": deleted_entities,
            "relations_deleted": deleted_relations,
            "observations_deleted": deleted_observations,
        }
    }

def delete_observations(observation_ids, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load_logs()
        logs.append({
            "id": f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "delete_observations",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
            "created_at": now_iso,
        })
        _save_logs(logs)

    def _enforce_limits():
        logs = _load_logs()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        mut_eps = {
            "create_entities", "create_relations", "add_observations",
            "delete_entities", "delete_relations", "delete_observations", "update_relation"
        }

        recent_ok = 0
        daily_ok = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in mut_eps:
                continue
            st = str(r.get("status", ""))
            if not (st.startswith("2") or st in ("ok", "success", "200", "201", "204")):
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_ok += 1
            if ts >= day_ago:
                daily_ok += 1

        if recent_ok >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded: too many successful write requests in the last minute.")
        if daily_ok >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("429", limit_err["error"]["code"])
        return limit_err

    if not isinstance(observation_ids, list) or len(observation_ids) == 0:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "observation_ids must be a non-empty array.")

    pat = re.compile(r"^mmt_obs_[0-9A-HJKMNP-TV-Z]{10,}$")
    for i, oid in enumerate(observation_ids):
        # IMPORTANT: do not reject datastore-consistent requests solely on prefix mismatch;
        # but the parameter schema requires this pattern, so enforce it.
        if not isinstance(oid, str) or not pat.match(oid):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"observation_ids[{i}] must match ^mmt_obs_[0-9A-HJKMNP-TV-Z]{{10,}}$")

    observations = _load("observations.json")
    events = _load("graph_events.json")
    if not isinstance(observations, list):
        observations = []
    if not isinstance(events, list):
        events = []

    obs_by_id = {o.get("id"): o for o in observations if isinstance(o, dict) and isinstance(o.get("id"), str)}
    missing = [oid for oid in observation_ids if oid not in obs_by_id]
    if missing:
        _log("404", "NOT_FOUND")
        return _err("NOT_FOUND", "One or more observation_ids do not exist.", missing_observation_ids=missing)

    def _new_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t_part = ""
        x = ms
        for _ in range(10):
            t_part = alphabet[x % 32] + t_part
            x //= 32
        import random
        rand_part = "".join(random.choice(alphabet) for _ in range(16))
        rid = f"{prefix}{t_part}{rand_part}"
        if rid in existing_ids:
            rand_part = "".join(random.choice(alphabet) for _ in range(16))
            rid = f"{prefix}{t_part}{rand_part}"
        return rid

    existing_evt_ids = {e.get("id") for e in events if isinstance(e, dict)}

    deleted = []
    changed = 0
    for oid in observation_ids:
        row = obs_by_id[oid]
        if row.get("status") == "deleted":
            # idempotent: already deleted counts as deleted but does not rewrite/event
            deleted.append({"id": oid, "status": "deleted", "already_deleted": True})
            continue

        # enforce lifecycle transition active -> deleted only
        if row.get("status") != "active":
            _log("409", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Observation {oid} cannot be deleted from status={row.get('status')}.")

        row["status"] = "deleted"
        row["deleted_at"] = now_iso
        row["updated_at"] = now_iso
        changed += 1
        deleted.append({"id": oid, "status": "deleted", "already_deleted": False})

        evt_id = _new_id("mmt_evt_", existing_evt_ids)
        existing_evt_ids.add(evt_id)
        events.append({
            "id": evt_id,
            "event_type": "observation.deleted",
            "entity_id": row.get("entity_id"),
            "relation_id": None,
            "observation_id": oid,
            "embedding_id": None,
            "actor": {"tool": "delete_observations"},
            "payload": {"observation": dict(row)},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    if changed == 0:
        # No success without effect: if all were already deleted, treat as NOT_FOUND? Real APIs vary.
        # Here, treat as idempotent success but with affected=0 would look mocky; return CONFLICT to indicate no-op.
        _log("409", "CONFLICT")
        return _err("CONFLICT", "No observations were deleted because all provided ids are already deleted.", deleted=deleted)

    _save("observations.json", observations)
    _save("graph_events.json", events)

    _log("200")
    return {
        "deleted": deleted,
        "requested": len(observation_ids),
        "deleted_count": changed,
        "deleted_at": now_iso,
    }

