            return _err("INVALID_TRANSITION", f"Relation {rid} cannot be deleted from status={row.get('status')}.")

        row["status"] = "deleted"
        row["deleted_at"] = now_iso
        row["updated_at"] = now_iso
        changed += 1
        deleted.append({"id": rid, "status": "deleted", "already_deleted": False})

        evt_id = _new_id("mmt_evt_", existing_evt_ids)
        existing_evt_ids.add(evt_id)
        events.append({
            "id": evt_id,
            "event_type": "relation.deleted",
            "entity_id": None,
            "relation_id": rid,
            "observation_id": None,
            "embedding_id": None,
            "actor": {"tool": "delete_relations"},
            "payload": {"relation": dict(row)},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    if changed == 0:
        _log("409", "CONFLICT")
        return _err("CONFLICT", "No relations were deleted because all provided ids are already deleted.", deleted=deleted)

    _save("relations.json", relations_rows)
    _save("graph_events.json", events)

    _log("200")
    return {
        "deleted": deleted,
        "requested": len(relation_ids),
        "deleted_count": changed,
        "deleted_at": now_iso,
    }

def get_relation(relation_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import time as _t, secrets
        ms = int(_t.time() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[ms % 32])
            ms //= 32
        for _ in range(16):
            chars.append(alphabet[secrets.randbelow(32)])
        return prefix + "".join(reversed(chars[:10])) + "".join(chars[10:])

    # validation
    pat = re.compile(r"^mmt_rel_[0-9A-HJKMNP-TV-Z]{10,}$")
    if not isinstance(relation_id, str) or not pat.match(relation_id):
        return _err("VALIDATION_ERROR", "relation_id must be a valid mmt_rel_* id", relation_id=relation_id)

    t0 = time.time()
    reqlogs = _load("request_logs.json")
    use_reqlog = isinstance(reqlogs, list)
    endpoint = "get_relation"

    relations = _load("relations.json")
    if not isinstance(relations, list):
        err = _err("UNAUTHORIZED", "You don’t have access to the graph")
        if use_reqlog:
            reqlogs.append({
                "id": _new_id("mmt_req_"),
                "endpoint": endpoint,
                "credential_id": None,
                "status": "error",
                "error_code": err["error"]["code"],
                "is_write": False,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", reqlogs)
        return err

    found = None
    for r in relations:
        if isinstance(r, dict) and r.get("id") == relation_id:
            found = r
            break

    if not found:
        err = _err("NOT_FOUND", "Relation not found", relation_id=relation_id)
        if use_reqlog:
            reqlogs.append({
                "id": _new_id("mmt_req_"),
                "endpoint": endpoint,
                "credential_id": None,
                "status": "error",
                "error_code": err["error"]["code"],
                "is_write": False,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            })
            _save("request_logs.json", reqlogs)
        return err

    if use_reqlog:
        reqlogs.append({
            "id": _new_id("mmt_req_"),
            "endpoint": endpoint,
            "credential_id": None,
            "status": "success",
            "error_code": None,
            "is_write": False,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save("request_logs.json", reqlogs)

    return {"object": "relation", "data": found}

def update_relation(relation_id, predicate=None, properties=None, confidence=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load_logs()
        logs.append({
            "id": f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "update_relation",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
            "created_at": now_iso,
        })
        _save_logs(logs)

    def _enforce_limits():
        logs = _load_logs()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        mut_eps = {
            "create_entities", "create_relations", "add_observations",
            "delete_entities", "delete_relations", "delete_observations", "update_relation"
        }

        recent_ok = 0
        daily_ok = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in mut_eps:
                continue
            st = str(r.get("status", ""))
            if not (st.startswith("2") or st in ("ok", "success", "200", "201", "204")):
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_ok += 1
            if ts >= day_ago:
                daily_ok += 1

        if recent_ok >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded: too many successful write requests in the last minute.")
        if daily_ok >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily write quota exceeded.")
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("429", limit_err["error"]["code"])
        return limit_err

    if not isinstance(relation_id, str) or not re.match(r"^mmt_rel_[0-9A-HJKMNP-TV-Z]{10,}$", relation_id):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "relation_id must match ^mmt_rel_[0-9A-HJKMNP-TV-Z]{10,}$")

    if predicate is None and properties is None and confidence is None:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one of predicate, properties, confidence must be provided.")

    if predicate is not None:
        if not isinstance(predicate, str):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "predicate must be a string.")
        if predicate.strip() == "":
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "predicate violates constraint predicate <> '' (predicate must be non-empty).")
        predicate = predicate.strip()

    if properties is not None and not isinstance(properties, dict):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "properties must be an object.")

    if confidence is not None:
        if not isinstance(confidence, (int, float)) or isinstance(confidence, bool):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "confidence must be a number.")
        if confidence < 0 or confidence > 1:
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "confidence violates constraint confidence >= 0 and confidence <= 1.")
        confidence = float(confidence)

    relations_rows = _load("relations.json")
    events = _load("graph_events.json")
    entities = _load("entities.json")
    if not isinstance(relations_rows, list):
        relations_rows = []
    if not isinstance(events, list):
        events = []
    if not isinstance(entities, list):
        entities = []

    rel = None
    for r in relations_rows:
        if isinstance(r, dict) and r.get("id") == relation_id:
            rel = r
            break
    if not rel:
        _log("404", "NOT_FOUND")
        return _err("NOT_FOUND", "Relation not found.", relation_id=relation_id)

    if rel.get("status") != "active":
        _log("409", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "update_relation only applies to relations in status='active'.")

    # If updating predicate, ensure uniqueness among active rows
    if predicate is not None:
        new_key = (rel.get("from_entity_id"), rel.get("to_entity_id"), predicate.lower())
        for r in relations_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == relation_id:
                continue
            if r.get("status") != "active":
                continue
            key = (r.get("from_entity_id"), r.get("to_entity_id"), str(r.get("predicate", "")).strip().lower())
            if key == new_key:
                _log("409", "CONFLICT")
                return _err("CONFLICT", "Update would violate unique(from_entity_id, to_entity_id, lower(predicate)) where status='active'.")

    # FK integrity rule: active relation cannot point to deleted entity
    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict)}
    fe = rel.get("from_entity_id")
    te = rel.get("to_entity_id")
    if ent_by_id.get(fe, {}).get("status") != "active" or ent_by_id.get(te, {}).get("status") != "active":
        _log("409", "CONFLICT")
        return _err("CONFLICT", "Active relation cannot point to a deleted entity; relation must be deleted instead.")

    before = dict(rel)

    changed = False
    if predicate is not None and predicate != rel.get("predicate"):
        rel["predicate"] = predicate
        changed = True
    if properties is not None and properties != rel.get("properties"):
        rel["properties"] = properties
        changed = True
    if confidence is not None and confidence != rel.get("confidence"):
        rel["confidence"] = confidence
        rel["confidence_updated_at"] = now_iso
        changed = True

    if not changed:
        _log("409", "CONFLICT")
        return _err("CONFLICT", "No changes applied (fields already have requested values).")

    rel["updated_at"] = now_iso

    def _new_id(prefix, existing_ids):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t_part = ""
        x = ms
        for _ in range(10):
            t_part = alphabet[x % 32] + t_part
            x //= 32
        import random
        rand_part = "".join(random.choice(alphabet) for _ in range(16))
        rid = f"{prefix}{t_part}{rand_part}"
        if rid in existing_ids:
            rand_part = "".join(random.choice(alphabet) for _ in range(16))
            rid = f"{prefix}{t_part}{rand_part}"
        return rid

    existing_evt_ids = {e.get("id") for e in events if isinstance(e, dict)}
    evt_id = _new_id("mmt_evt_", existing_evt_ids)
    events.append({
        "id": evt_id,
        "event_type": "relation.updated",
        "entity_id": None,
        "relation_id": relation_id,
        "observation_id": None,
        "embedding_id": None,
        "actor": {"tool": "update_relation"},
        "payload": {"before": before, "after": dict(rel)},
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    })

    _save("relations.json", relations_rows)
    _save("graph_events.json", events)

    _log("200")
    return {"relation": rel, "updated_at": now_iso}

def read_graph(include_deleted=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "read_graph",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _enforce_read_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        recent_ok = 0
        daily_ok = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in ("read_graph", "get_decayed_graph"):
                continue
            st = str(r.get("status", ""))
            if not (st.startswith("2") or st == "ok" or st == "success"):
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_ok += 1
            if ts >= day_ago:
                daily_ok += 1
        if recent_ok >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if daily_ok >= 50000:
            return _err("QUOTA_EXCEEDED", "Read quota exceeded.")
        return None

    lim_err = _enforce_read_limits()
    if lim_err:
        _log("429", lim_err["error"]["code"])
        return lim_err

    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean if provided")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit <= 0 or limit > 1000:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")

    # Cursor is opaque in API; accept arbitrary strings. If it's our encoded cursor, use it; otherwise treat as a "start after id".
    def _parse_cursor(cur):
        if cur is None:
            return {"mode": "offset", "i": 0}
        if not isinstance(cur, str):
            return None
        # try base64 json first
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("i"), int) and obj["i"] >= 0:
                return {"mode": "offset", "i": obj["i"]}
        except Exception:
            pass
        # fallback: treat as an id cursor; we will find it in entity ordering
        return {"mode": "id", "id": cur}

    def _make_cursor_offset(i):
        raw = json.dumps({"i": i}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    state = _parse_cursor(cursor)
    if state is None:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    entities = _load("entities.json")
    relations_rows = _load("relations.json")
    observations = _load("observations.json")
    if not isinstance(entities, list): entities = []
    if not isinstance(relations_rows, list): relations_rows = []
    if not isinstance(observations, list): observations = []

    def _visible(row):
        if not isinstance(row, dict):
            return False
        if include_deleted:
            return True
        return row.get("status") == "active"

    ents = [e for e in entities if _visible(e)]
    rels = [r for r in relations_rows if _visible(r)]
    obs = [o for o in observations if _visible(o)]

    # Deterministic ordering by created_at then id
    def _key(r):
        ca = r.get("created_at") if isinstance(r, dict) else ""
        if not isinstance(ca, str):
            ca = ""
        rid = r.get("id") if isinstance(r, dict) else ""
        if not isinstance(rid, str):
            rid = ""
        return (ca, rid)

    ents.sort(key=_key)
    rels.sort(key=_key)
    obs.sort(key=_key)

    start_i = 0
    if state["mode"] == "offset":
        start_i = state["i"]
        if start_i < 0:
            start_i = 0
    else:
        # cursor as id; find it in ents ordering; if not found, start at 0 (do not error)
        cid = state.get("id")
        idx = None
        if isinstance(cid, str):
            for j, e in enumerate(ents):
                if e.get("id") == cid:
                    idx = j + 1
                    break
        start_i = idx if idx is not None else 0

    # limit is across all collections; we'll allocate page by taking entities first, then relations, then observations
    remaining = limit
    page_ents = ents[start_i:start_i + remaining]
    remaining -= len(page_ents)

    page_rels = []
    page_obs = []
    if remaining > 0:
        page_rels = rels[:remaining]
        remaining -= len(page_rels)
    if remaining > 0:
        page_obs = obs[:remaining]
        remaining -= len(page_obs)

    # compute has_more based on entity pagination only (cursor defined over entities)
    next_i = start_i + len(page_ents)
    has_more = next_i < len(ents)
    next_cursor = _make_cursor_offset(next_i) if has_more else None

    _log("200", None)
    return {
        "entities": page_ents,
        "relations": page_rels,
        "observations": page_obs,
        "meta": {
            "total": {"entities": len(ents), "relations": len(rels), "observations": len(obs)},
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def search_nodes(query, entity_type=None, status=None, sort=None, cursor=None, limit=None, **_extra):
