                return None
            i = obj.get("i")
            if not isinstance(i, int) or i < 0:
                return None
            return {"i": i}
        except Exception:
            return None

    def _make_cursor(i):
        raw = json.dumps({"i": i}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validation
    if not isinstance(query, str) or not query.strip():
