        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    state = _parse_cursor(cursor)
    if state is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    # Load data
    try:
        entities = _load("entities.json")
        observations = _load("observations.json")
    except Exception:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not initialized")

    if not isinstance(entities, list) or not isinstance(observations, list):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not initialized")

    q = query.strip().lower()
    # Tokenize (simple lexical "indexed" feel): words >= 2 chars
    toks = [t for t in re.split(r"\W+", q) if len(t) >= 2]
    if not toks:
        toks = [q]

    # Build observation hits by entity_id (active observations only for search)
    obs_by_entity = {}
    for o in observations:
        try:
            if o.get("status") != "active":
                continue
            eid = o.get("entity_id")
            if not isinstance(eid, str):
                continue
            txt = (o.get("content") or "")
            if not isinstance(txt, str):
                continue
            obs_by_entity.setdefault(eid, []).append(txt.lower())
        except Exception:
            continue

    # Score entities
    scored = []
    for e in entities:
        try:
            if e.get("status") != status:
                continue
            if entity_type is not None and (e.get("entity_type") != entity_type):
                continue
            name = (e.get("name") or "")
            summary = (e.get("summary") or "")
            if not isinstance(name, str) or not isinstance(summary, str):
                name = str(name) if name is not None else ""
                summary = str(summary) if summary is not None else ""
            text_name = name.lower()
            text_summary = summary.lower()
            obs_texts = obs_by_entity.get(e.get("id") or "", [])
            # Simple relevance: weighted token occurrences
            score = 0.0
            for t in toks:
                if t in text_name:
                    score += 5.0
                if t in text_summary:
                    score += 2.0
                for ot in obs_texts:
                    if t in ot:
                        score += 1.0
            if score <= 0:
                continue
            scored.append((score, e))
        except Exception:
            continue

    # Sort
    if sort == "relevance":
        scored.sort(key=lambda x: (x[0], x[1].get("updated_at") or "", x[1].get("id") or ""), reverse=True)
        ordered = [e for _, e in scored]
    elif sort == "created_at":
        ordered = sorted([e for _, e in scored], key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)
    elif sort == "updated_at":
        ordered = sorted([e for _, e in scored], key=lambda r: (r.get("updated_at") or r.get("created_at") or "", r.get("id") or ""), reverse=True)
    else:  # name
        ordered = sorted([e for _, e in scored], key=lambda r: ((r.get("name") or "").lower(), r.get("id") or ""))

    start = state["i"]
    if start > len(ordered):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor points past end")
    page = ordered[start:start + limit]
    next_i = start + len(page)
    next_cursor = _make_cursor(next_i) if next_i < len(ordered) else None

    resp = {
        "entities": page,
        "meta": {
            "total": len(ordered),
            "returned": len(page),
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor,
            "limit": limit,
            "sort": sort,
            "status": status,
            "entity_type": entity_type,
            "query": query,
        }
    }
    _log("ok", None)
    return resp

def open_nodes(names, include_deleted=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "open_nodes"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validation
    if not isinstance(names, list) or len(names) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "names is required and must be a non-empty array of strings")
    for i, n in enumerate(names):
        if not isinstance(n, str) or not n.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"names[{i}] must be a non-empty string")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean if provided")
    include_deleted = bool(include_deleted) if include_deleted is not None else False

    entities = _load("entities.json")
    if not isinstance(entities, list):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not initialized")

    wanted = [n.strip().lower() for n in names]
    wanted_set = set(wanted)

    matches = []
    for e in entities:
        try:
            nm = e.get("name")
            if not isinstance(nm, str):
                continue
            if nm.strip().lower() not in wanted_set:
                continue
            if not include_deleted and e.get("status") != "active":
                continue
            matches.append(e)
        except Exception:
            continue

    # If multiple entities share a name, return all matches (already satisfied).
    resp = {
        "entities": matches,
        "meta": {
            "requested": len(names),
            "returned": len(matches),
            "include_deleted": include_deleted,
        }
    }
    _log("ok", None)
    return resp

def semantic_search(query, model=None, entity_type=None, status=None, min_similarity=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "semantic_search"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    def _parse_cursor(cur):
        if cur is None:
            return {"i": 0}
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "i" not in obj:
                return None
            i = obj.get("i")
            if not isinstance(i, int) or i < 0:
                return None
            return {"i": i}
        except Exception:
            return None

    def _make_cursor(i):
        raw = json.dumps({"i": i}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validation
    if not isinstance(query, str) or not query.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")
    if model is not None and not isinstance(model, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model must be a string if provided")
    if entity_type is not None and not isinstance(entity_type, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entity_type must be a string if provided")
    if status is None:
        status = "active"
    if status not in ("active", "deleted"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted")
    if min_similarity is None:
        min_similarity = -1.0
    if not isinstance(min_similarity, (int, float)) or math.isnan(float(min_similarity)) or min_similarity < -1.0 or min_similarity > 1.0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min_similarity must be a number between -1.0 and 1.0")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit <= 0 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    state = _parse_cursor(cursor)
    if state is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    # Load
    entities = _load("entities.json")
    embeddings = _load("embeddings.json")
    if not isinstance(entities, list) or not isinstance(embeddings, list):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not initialized")

    # Determine default model and dims
    # If model not provided: choose most common embeddings.model, else fall back to 'text-embedding-3-small'
    if model is None:
        freq = {}
        for em in embeddings:
            try:
                m = em.get("model")
                if isinstance(m, str) and m:
                    freq[m] = freq.get(m, 0) + 1
            except Exception:
                continue
        model = max(freq.items(), key=lambda kv: kv[1])[0] if freq else "text-embedding-3-small"

    # Pick dimensions from any embedding row for that model; default 1536
    dims = None
    for em in embeddings:
        try:
            if em.get("model") == model and isinstance(em.get("dimensions"), int) and em.get("dimensions") > 0:
                dims = em["dimensions"]
                break
        except Exception:
            continue
    if dims is None:
        dims = 1536

    # Deterministic "embed" offline (no external model): hashed bag -> unit vector
    # This is a stand-in for real embedding; still enables stable similarity ordering.
    def _embed(text, d):
        h = hashlib.sha256(text.encode("utf-8")).digest()
        vec = [0.0] * d
        # Fill by expanding hash with counters
        for i in range(d):
            b = hashlib.sha256(h + i.to_bytes(4, "big")).digest()
            # Map first 4 bytes to [-1,1]
            v = int.from_bytes(b[:4], "big") / 0xFFFFFFFF
            vec[i] = (v * 2.0) - 1.0
        # Normalize
        norm = math.sqrt(sum(x * x for x in vec)) or 1.0
        return [x / norm for x in vec]

    qvec = _embed(query.strip(), dims)

    def _cos(a, b):
        # a,b assumed same length and normalized-ish
        s = 0.0
        for i in range(min(len(a), len(b))):
            s += a[i] * b[i]
        # Clamp
        if s > 1.0: s = 1.0
        if s < -1.0: s = -1.0
        return s

    # Index entities by id
    ent_by_id = {}
    for e in entities:
        if isinstance(e, dict) and isinstance(e.get("id"), str):
            ent_by_id[e["id"]] = e

    # Collect candidates with ready embeddings and matching model
    scored = []
    for em in embeddings:
        try:
            if em.get("model") != model:
                continue
            if em.get("status") != "ready":
                continue
            eid = em.get("entity_id")
            if not isinstance(eid, str):
                continue
            e = ent_by_id.get(eid)
            if not e:
                continue
            if e.get("status") != status:
                continue
            if entity_type is not None and e.get("entity_type") != entity_type:
                continue
            vec = em.get("vector")
            if not isinstance(vec, list) or len(vec) == 0:
                continue
            # Ensure numeric
            ok = True
            for x in vec[:10]:
                if not isinstance(x, (int, float)):
                    ok = False
                    break
            if not ok:
                continue
            sim = _cos(qvec, vec)
            if sim < float(min_similarity):
                continue
            scored.append((sim, e.get("updated_at") or e.get("created_at") or "", e.get("id") or "", e))
        except Exception:
            continue

    # Sort by similarity desc, then updated_at desc, then id
    scored.sort(key=lambda t: (t[0], t[1], t[2]), reverse=True)
    ordered = [t[3] for t in scored]
    sims = [t[0] for t in scored]

    start = state["i"]
    if start > len(ordered):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor points past end")

    end = min(start + limit, len(ordered))
    page_entities = ordered[start:end]
    page_sims = sims[start:end]
    next_cursor = _make_cursor(end) if end < len(ordered) else None

    # Return matches with similarity
    results = []
    for e, s in zip(page_entities, page_sims):
        results.append({"entity": e, "similarity": s})

    resp = {
        "results": results,
        "meta": {
            "total": len(ordered),
            "returned": len(results),
            "has_more": next_cursor is not None,
            "next_cursor": next_cursor,
            "limit": limit,
            "model": model,
            "status": status,
            "entity_type": entity_type,
            "min_similarity": float(min_similarity),
        }
    }
    _log("ok", None)
    return resp

def get_entity_embedding(entity_id, model=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _as_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, error_code=None, meta=None, started=None):
        started = started or datetime.datetime.utcnow()
        ended = datetime.datetime.utcnow()
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": "req_" + ended.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ended.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    started = datetime.datetime.utcnow()
    endpoint = "get_entity_embedding"

    try:
        if not isinstance(entity_id, str) or not re.match(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{26}$", entity_id):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "entity_id"}, started)
            return _err("VALIDATION_ERROR", "Invalid entity_id format.", field="entity_id")
        if model is not None and not isinstance(model, str):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "model"}, started)
            return _err("VALIDATION_ERROR", "model must be a string.", field="model")
        if isinstance(model, str) and model.strip() == "":
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "model"}, started)
            return _err("VALIDATION_ERROR", "model cannot be empty.", field="model")

        entities = _load("entities.json")
        ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == entity_id), None)
        if not ent:
            _log(endpoint, "error", "NOT_FOUND", {"entity_id": entity_id}, started)
            return _err("NOT_FOUND", "Entity not found.", entity_id=entity_id)

        embeddings = _load("embeddings.json")
        if not isinstance(embeddings, list):
            embeddings = []

        chosen = None
        if model is not None:
            m = model.strip()
            chosen = next((x for x in embeddings if isinstance(x, dict) and x.get("entity_id") == entity_id and x.get("model") == m), None)
            if not chosen:
                _log(endpoint, "error", "NOT_FOUND", {"entity_id": entity_id, "model": m}, started)
                return _err("NOT_FOUND", "Embedding not found for requested model.", entity_id=entity_id, model=m)
        else:
            # Default selection: prefer ready, then most recently updated/created
            cands = [x for x in embeddings if isinstance(x, dict) and x.get("entity_id") == entity_id]
            if not cands:
                _log(endpoint, "error", "NOT_FOUND", {"entity_id": entity_id}, started)
                return _err("NOT_FOUND", "No embeddings found for entity.", entity_id=entity_id)

            ready = [x for x in cands if x.get("status") == "ready"]
            pool = ready if ready else cands

            def _score(x):
                t = _as_dt(x.get("updated_at")) or _as_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                if t.tzinfo is None:
                    t = t.replace(tzinfo=datetime.timezone.utc)
                return t

            pool.sort(key=_score, reverse=True)
            chosen = pool[0]

        # Per rule: if not ready, return status and last_error rather than vector
        out = dict(chosen)
        if out.get("status") != "ready":
            out["vector"] = None

        _log(endpoint, "ok", None, {"entity_id": entity_id, "model": out.get("model"), "status": out.get("status")}, started)
        return {"data": out}
    except Exception as e:
        _log(endpoint, "error", "VALIDATION_ERROR", {"exception": str(e)}, started)
        return _err("VALIDATION_ERROR", "Request failed.", details=str(e))

def get_entity_history(entity_id, cursor=None, limit=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _as_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, error_code=None, meta=None, started=None):
        started = started or datetime.datetime.utcnow()
        ended = datetime.datetime.utcnow()
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": "req_" + ended.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ended.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if not isinstance(s, str) or s.strip() == "":
            return None
        t = s.strip()
        pad = "=" * ((4 - (len(t) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((t + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            return "__bad__"

    started = datetime.datetime.utcnow()
    endpoint = "get_entity_history"

    try:
        if not isinstance(entity_id, str) or not re.match(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{26}$", entity_id):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "entity_id"}, started)
            return _err("VALIDATION_ERROR", "Invalid entity_id format.", field="entity_id")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit <= 0 or limit > 200:
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "limit"}, started)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

        cobj = None
        if cursor is not None:
            cobj = _decode_cursor(cursor)
            if cobj == "__bad__" or not isinstance(cobj, dict) or "pos" not in cobj or not isinstance(cobj["pos"], int):
                _log(endpoint, "error", "VALIDATION_ERROR", {"field": "cursor"}, started)
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        entities = _load("entities.json")
        ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == entity_id), None)
        if not ent:
            _log(endpoint, "error", "NOT_FOUND", {"entity_id": entity_id}, started)
            return _err("NOT_FOUND", "Entity not found.", entity_id=entity_id)

        events = _load("graph_events.json")
        if not isinstance(events, list):
            events = []

        # Full history from events (include deleted events), reverse chronological
        filtered = [ev for ev in events if isinstance(ev, dict) and ev.get("entity_id") == entity_id]
        def _key(ev):
            dt = _as_dt(ev.get("occurred_at")) or _as_dt(ev.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt, str(ev.get("id", "")))
        filtered.sort(key=_key, reverse=True)

        pos = cobj["pos"] if cobj else 0
        if pos < 0 or pos > len(filtered):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "cursor"}, started)
            return _err("VALIDATION_ERROR", "Invalid cursor position.", field="cursor")

        page = filtered[pos:pos + limit]
        next_pos = pos + len(page)
        next_cursor = _encode_cursor({"pos": next_pos}) if next_pos < len(filtered) else None

        _log(endpoint, "ok", None, {"entity_id": entity_id, "returned": len(page), "total": len(filtered)}, started)
        return {
            "data": page,
            "meta": {
                "entity_id": entity_id,
                "total": len(filtered),
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
            },
        }
    except Exception as e:
        _log(endpoint, "error", "VALIDATION_ERROR", {"exception": str(e)}, started)
        return _err("VALIDATION_ERROR", "Request failed.", details=str(e))

def get_relation_history(relation_id, cursor=None, limit=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _as_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, error_code=None, meta=None, started=None):
        started = started or datetime.datetime.utcnow()
        ended = datetime.datetime.utcnow()
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": "req_" + ended.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ended.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if not isinstance(s, str) or s.strip() == "":
            return None
        t = s.strip()
        pad = "=" * ((4 - (len(t) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((t + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            return "__bad__"

    started = datetime.datetime.utcnow()
    endpoint = "get_relation_history"

    try:
        if not isinstance(relation_id, str) or not re.match(r"^mmt_rel_[0-9A-HJKMNP-TV-Z]{26}$", relation_id):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "relation_id"}, started)
            return _err("VALIDATION_ERROR", "Invalid relation_id format.", field="relation_id")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit <= 0 or limit > 200:
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "limit"}, started)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

        cobj = None
        if cursor is not None:
            cobj = _decode_cursor(cursor)
            if cobj == "__bad__" or not isinstance(cobj, dict) or "pos" not in cobj or not isinstance(cobj["pos"], int):
                _log(endpoint, "error", "VALIDATION_ERROR", {"field": "cursor"}, started)
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        relations = _load("relations.json")
        rel = next((r for r in relations if isinstance(r, dict) and r.get("id") == relation_id), None)
        if not rel:
            _log(endpoint, "error", "NOT_FOUND", {"relation_id": relation_id}, started)
            return _err("NOT_FOUND", "Relation not found.", relation_id=relation_id)

        events = _load("graph_events.json")
        if not isinstance(events, list):
            events = []

        filtered = [ev for ev in events if isinstance(ev, dict) and ev.get("relation_id") == relation_id]

        def _key(ev):
            dt = _as_dt(ev.get("occurred_at")) or _as_dt(ev.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt, str(ev.get("id", "")))

        filtered.sort(key=_key, reverse=True)

        pos = cobj["pos"] if cobj else 0
        if pos < 0 or pos > len(filtered):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "cursor"}, started)
            return _err("VALIDATION_ERROR", "Invalid cursor position.", field="cursor")

        page = filtered[pos:pos + limit]
        next_pos = pos + len(page)
        next_cursor = _encode_cursor({"pos": next_pos}) if next_pos < len(filtered) else None

        _log(endpoint, "ok", None, {"relation_id": relation_id, "returned": len(page), "total": len(filtered)}, started)
        return {
            "data": page,
            "meta": {
                "relation_id": relation_id,
                "total": len(filtered),
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
            },
        }
    except Exception as e:
        _log(endpoint, "error", "VALIDATION_ERROR", {"exception": str(e)}, started)
        return _err("VALIDATION_ERROR", "Request failed.", details=str(e))

def get_graph_at_time(at, include_deleted=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _as_dt_required(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s = s.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _as_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, error_code=None, meta=None, started=None):
        started = started or datetime.datetime.utcnow()
        ended = datetime.datetime.utcnow()
        latency_ms = int((ended - started).total_seconds() * 1000)
        row = {
            "id": "req_" + ended.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": ended.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(s):
        if not isinstance(s, str) or s.strip() == "":
            return None
        t = s.strip()
        pad = "=" * ((4 - (len(t) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((t + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            return "__bad__"

    started = datetime.datetime.utcnow()
    endpoint = "get_graph_at_time"

    try:
        at_dt = _as_dt_required(at)
        if at_dt is None:
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "at"}, started)
            return _err("VALIDATION_ERROR", "Invalid 'at' timestamp; must be ISO-8601 date-time.", field="at")

        if include_deleted is None:
            include_deleted = False
        if not isinstance(include_deleted, bool):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "include_deleted"}, started)
            return _err("VALIDATION_ERROR", "include_deleted must be boolean.", field="include_deleted")

        if limit is None:
            limit = 200
        if not isinstance(limit, int) or limit <= 0 or limit > 1000:
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "limit"}, started)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.", field="limit")

        cobj = None
        if cursor is not None:
            cobj = _decode_cursor(cursor)
            if cobj == "__bad__" or not isinstance(cobj, dict) or "pos" not in cobj or not isinstance(cobj["pos"], int):
                _log(endpoint, "error", "VALIDATION_ERROR", {"field": "cursor"}, started)
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        events = _load("graph_events.json")
        if not isinstance(events, list):
            events = []

        # Select events occurred_at <= at; apply in occurred_at asc then id asc
        selected = []
        for ev in events:
            if not isinstance(ev, dict):
                continue
            odt = _as_dt(ev.get("occurred_at"))
            if odt is None:
                continue
            # Normalize timezone-less to UTC for comparisons
            if odt.tzinfo is None:
                odt = odt.replace(tzinfo=datetime.timezone.utc)
            cmp_at = at_dt
            if cmp_at.tzinfo is None:
                cmp_at = cmp_at.replace(tzinfo=datetime.timezone.utc)
            if odt <= cmp_at:
                selected.append(ev)

        def _sort_key(ev):
            odt = _as_dt(ev.get("occurred_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if odt.tzinfo is None:
                odt = odt.replace(tzinfo=datetime.timezone.utc)
            return (odt, str(ev.get("id", "")))

        selected.sort(key=_sort_key)

        # Replay events
        entities = {}
        relations = {}
        observations = {}

        def _apply_snapshot(store, key, snap):
            if isinstance(snap, dict) and snap.get("id"):
                store[snap.get("id")] = dict(snap)

        for ev in selected:
            et = ev.get("event_type")
            payload = ev.get("payload") if isinstance(ev.get("payload"), dict) else {}
            if et == "entity.created" or et == "entity.updated":
                snap = payload.get("entity") or payload.get("after") or payload.get("snapshot") or payload
                _apply_snapshot(entities, "id", snap)
            elif et == "entity.deleted":
                eid = ev.get("entity_id")
                if eid and eid in entities:
                    row = dict(entities[eid])
                    row["status"] = "deleted"
                    row["deleted_at"] = ev.get("occurred_at") or row.get("deleted_at")
                    entities[eid] = row
            elif et == "relation.created" or et == "relation.updated":
                snap = payload.get("relation") or payload.get("after") or payload.get("snapshot") or payload
                _apply_snapshot(relations, "id", snap)
            elif et == "relation.deleted":
                rid = ev.get("relation_id")
                if rid and rid in relations:
                    row = dict(relations[rid])
                    row["status"] = "deleted"
                    row["deleted_at"] = ev.get("occurred_at") or row.get("deleted_at")
                    relations[rid] = row
            elif et == "observation.created":
                snap = payload.get("observation") or payload.get("after") or payload.get("snapshot") or payload
                _apply_snapshot(observations, "id", snap)
            elif et == "observation.deleted":
                oid = ev.get("observation_id")
                if oid and oid in observations:
                    row = dict(observations[oid])
                    row["status"] = "deleted"
                    row["deleted_at"] = ev.get("occurred_at") or row.get("deleted_at")
                    observations[oid] = row
            # Embedding events ignored for graph snapshot state

        # Filter by deletion status at time (default exclude deleted)
        ent_list = list(entities.values())
        rel_list = list(relations.values())
        obs_list = list(observations.values())

        if not include_deleted:
            ent_list = [e for e in ent_list if isinstance(e, dict) and e.get("status") != "deleted"]
            rel_list = [r for r in rel_list if isinstance(r, dict) and r.get("status") != "deleted"]
            obs_list = [o for o in obs_list if isinstance(o, dict) and o.get("status") != "deleted"]

        # Deterministic ordering for paging
        def _row_key(r):
            return str(r.get("id", ""))

        ent_list.sort(key=_row_key)
        rel_list.sort(key=_row_key)
        obs_list.sort(key=_row_key)

        flat = (
            [{"kind": "entity", "id": r.get("id"), "row": r} for r in ent_list] +
            [{"kind": "relation", "id": r.get("id"), "row": r} for r in rel_list] +
            [{"kind": "observation", "id": r.get("id"), "row": r} for r in obs_list]
        )
        flat.sort(key=lambda x: (x["kind"], x["id"]))

        pos = cobj["pos"] if cobj else 0
        if pos < 0 or pos > len(flat):
            _log(endpoint, "error", "VALIDATION_ERROR", {"field": "cursor"}, started)
            return _err("VALIDATION_ERROR", "Invalid cursor position.", field="cursor")

        page = flat[pos:pos + limit]
        next_pos = pos + len(page)
        next_cursor = _encode_cursor({"pos": next_pos}) if next_pos < len(flat) else None

        # Return items split by collection, but page is across all kinds
        out_entities, out_relations, out_observations = [], [], []
        for item in page:
            if item["kind"] == "entity":
                out_entities.append(item["row"])
            elif item["kind"] == "relation":
                out_relations.append(item["row"])
            else:
                out_observations.append(item["row"])

        _log(endpoint, "ok", None, {
            "at": at,
            "include_deleted": include_deleted,
            "returned": len(page),
            "total": len(flat),
        }, started)

        return {
            "data": {
                "entities": out_entities,
                "relations": out_relations,
                "observations": out_observations,
            },
            "meta": {
                "at": at,
                "include_deleted": include_deleted,
                "total": len(flat),
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
                "returned_counts": {
                    "entities": len(out_entities),
                    "relations": len(out_relations),
                    "observations": len(out_observations),
                },
            },
        }
    except Exception as e:
        _log(endpoint, "error", "VALIDATION_ERROR", {"exception": str(e)}, started)
        return _err("VALIDATION_ERROR", "Request failed.", details=str(e))

def get_decayed_graph(as_of=None, half_life_seconds=None, min_confidence=None, include_deleted=None, entity_ids=None, root_entity_id=None, max_hops=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, math, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "get_decayed_graph",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
            "created_at": now_iso,
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _enforce_read_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        recent_ok = 0
        daily_ok = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in ("read_graph", "get_decayed_graph"):
                continue
            st = str(r.get("status", ""))
            if not (st.startswith("2") or st == "ok" or st == "success"):
                continue
            ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                recent_ok += 1
            if ts >= day_ago:
                daily_ok += 1
        if recent_ok >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if daily_ok >= 50000:
            return _err("QUOTA_EXCEEDED", "Read quota exceeded.")
        return None

    lim_err = _enforce_read_limits()
    if lim_err:
        _log("429", lim_err["error"]["code"])
        return lim_err

    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean if provided")

    asof_dt = _parse_dt(as_of) if as_of is not None else now
    if as_of is not None and asof_dt is None:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "as_of must be a valid RFC3339 datetime string")

    if half_life_seconds is None:
        half_life_seconds = 86400.0
    if isinstance(half_life_seconds, bool) or not isinstance(half_life_seconds, (int, float)) or float(half_life_seconds) <= 0:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "half_life_seconds must be a positive number")
    half_life_seconds = float(half_life_seconds)

    # Relax min_confidence validation: allow any number; clamp to [0,1] for filtering.
    if min_confidence is None:
        min_confidence = 0.0
    if isinstance(min_confidence, bool) or not isinstance(min_confidence, (int, float)):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min_confidence must be a number")
    min_conf = float(min_confidence)
    if min_conf < 0:
        min_conf = 0.0
    if min_conf > 1:
        min_conf = 1.0

    if max_hops is None:
        max_hops = 1
    if not isinstance(max_hops, int) or max_hops < 0:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_hops must be an integer >= 0")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")

    ent_ulid_pat = re.compile(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{26}$")
    if entity_ids is not None:
        if not isinstance(entity_ids, list):
            _log("400", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "entity_ids must be an array when provided")
        for eid in entity_ids:
            if not isinstance(eid, str) or not ent_ulid_pat.match(eid):
                _log("400", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid entity id format in entity_ids", entity_id=eid)

    if root_entity_id is not None and (not isinstance(root_entity_id, str) or not ent_ulid_pat.match(root_entity_id)):
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "root_entity_id must be a valid mmt_ent_* ULID when provided", root_entity_id=root_entity_id)

    # Cursor: accept opaque; support our offset cursor or id cursor
    def _parse_cursor(cur):
        if cur is None:
            return {"mode": "offset", "i": 0}
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("i"), int) and obj["i"] >= 0:
                return {"mode": "offset", "i": obj["i"]}
        except Exception:
            pass
        return {"mode": "id", "id": cur}

    def _make_cursor_offset(i):
        raw = json.dumps({"i": i}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    state = _parse_cursor(cursor)
    if state is None:
        _log("400", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    entities = _load("entities.json")
    relations_rows = _load("relations.json")
    observations = _load("observations.json")
    if not isinstance(entities, list): entities = []
    if not isinstance(relations_rows, list): relations_rows = []
    if not isinstance(observations, list): observations = []

    def _visible(row):
        if not isinstance(row, dict):
            return False
        if include_deleted:
            return True
        return row.get("status") == "active"

    ent_by_id = {e.get("id"): e for e in entities if isinstance(e, dict) and isinstance(e.get("id"), str)}

    # Build candidate entity set
    candidates = [e for e in entities if _visible(e)]

    if entity_ids is not None:
        ids = set(entity_ids)
        candidates = [e for e in candidates if e.get("id") in ids]

    # Expand subgraph from root if provided
    if root_entity_id is not None:
        # BFS over active-or-included relations
        adj = {}
        for r in relations_rows:
            if not _visible(r):
                continue
            a = r.get("from_entity_id"); b = r.get("to_entity_id")
            if isinstance(a, str) and isinstance(b, str):
                adj.setdefault(a, set()).add(b)
                adj.setdefault(b, set()).add(a)
        seen = {root_entity_id}
        frontier = {root_entity_id}
        for _ in range(max_hops):
            nxt = set()
            for n in frontier:
                for m in adj.get(n, ()):
                    if m not in seen:
                        seen.add(m)
                        nxt.add(m)
            frontier = nxt
            if not frontier:
                break
        candidates = [e for e in candidates if e.get("id") in seen]

    def _base_time_for(row):
        # max(updated_at, confidence_updated_at, observed_at) when present
        times = []
        for k in ("updated_at", "confidence_updated_at", "observed_at"):
            dt = _parse_dt(row.get(k))
            if dt is not None:
                times.append(dt)
        if not times:
            ca = _parse_dt(row.get("created_at"))
            return ca if ca is not None else asof_dt
        return max(times)

    def _clamp01(x):
        try:
            x = float(x)
        except Exception:
            x = 0.0
        if x < 0: x = 0.0
        if x > 1: x = 1.0
        return x

    ln2 = math.log(2.0)

    def _decayed(conf, base_dt):
        c = _clamp01(conf)
        if base_dt is None:
            return c
        age = (asof_dt - base_dt).total_seconds()
        if age <= 0:
            return c
        return _clamp01(c * math.exp(-ln2 * (age / half_life_seconds)))

    # Apply decay + threshold
    decayed_entities = []
    for e in candidates:
        base_dt = _base_time_for(e)
        dc = _decayed(e.get("confidence", 0.0), base_dt)
        if dc >= min_conf:
            ee = dict(e)
            ee["decayed_confidence"] = dc
            decayed_entities.append(ee)

    # Order for pagination
    decayed_entities.sort(key=lambda r: ((r.get("created_at") or ""), (r.get("id") or "")))

    start_i = 0
    if state["mode"] == "offset":
        start_i = state["i"]
        if start_i < 0:
            start_i = 0
    else:
        cid = state.get("id")
        idx = None
        if isinstance(cid, str):
            for j, e in enumerate(decayed_entities):
                if e.get("id") == cid:
                    idx = j + 1
                    break
        start_i = idx if idx is not None else 0

    page_entities = decayed_entities[start_i:start_i + limit]
    page_entity_ids = {e.get("id") for e in page_entities if isinstance(e.get("id"), str)}

    # Attach relations/observations connected to the page's entities (subject to decay + threshold as well)
    decayed_relations = []
    for r in relations_rows:
        if not _visible(r):
            continue
        fe = r.get("from_entity_id"); te = r.get("to_entity_id")
        if fe in page_entity_ids or te in page_entity_ids:
            base_dt = _base_time_for(r)
            dc = _decayed(r.get("confidence", 0.0), base_dt)
            if dc >= min_conf:
                rr = dict(r)
                rr["decayed_confidence"] = dc
                decayed_relations.append(rr)

    decayed_observations = []
    for o in observations:
        if not _visible(o):
            continue
        if o.get("entity_id") in page_entity_ids:
            base_dt = _base_time_for(o)
            dc = _decayed(o.get("confidence", 0.0), base_dt)
            if dc >= min_conf:
                oo = dict(o)
                oo["decayed_confidence"] = dc
                decayed_observations.append(oo)

    next_i = start_i + len(page_entities)
    has_more = next_i < len(decayed_entities)
    next_cursor = _make_cursor_offset(next_i) if has_more else None

    _log("200", None)
    return {
        "entities": page_entities,
        "relations": decayed_relations,
        "observations": decayed_observations,
        "meta": {
            "as_of": asof_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "half_life_seconds": half_life_seconds,
            "min_confidence": min_conf,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "total_entities_after_filter": len(decayed_entities),
        },
    }

def force_generate_embedding(entity_id, model=None, overwrite=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)
    def _now_iso():
        return _now().isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": None,
            "endpoint": "force_generate_embedding",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        logs = _load("request_logs.json")
        req["id"] = f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}"
        logs.append(req)
        _save("request_logs.json", logs)

    def _validate_ulid(prefix, s):
        if not isinstance(s, str):
            return False
        pat = r"^" + re.escape(prefix) + r"[0-9A-HJKMNP-TV-Z]{26}$"
        return re.match(pat, s) is not None

    def _new_id(prefix, rows):
        # deterministic enough for offline use
        return f"{prefix}{int(time.time()*1000)}_{len(rows)+1}"

    # ---- Validate
    if not isinstance(entity_id, str) or not _validate_ulid("mmt_ent_", entity_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entity_id must be a valid entity ULID")
    if model is not None and not isinstance(model, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model must be a string")
    if model is None or model.strip() == "":
        # configured default: pick most common model in db if present; else a fixed default
        embs = _load("embeddings.json")
        counts = {}
        for e in embs:
            if isinstance(e, dict) and isinstance(e.get("model"), str) and e.get("model"):
                counts[e["model"]] = counts.get(e["model"], 0) + 1
        model = (max(counts.items(), key=lambda kv: kv[1])[0] if counts else "text-embedding-3-small")
    model = model.strip()
    if overwrite is None:
        overwrite = False
    if not isinstance(overwrite, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "overwrite must be a boolean")

    # ---- Load
    entities = _load("entities.json")
    observations = _load("observations.json")
    embeddings = _load("embeddings.json")
    graph_events = _load("graph_events.json")

    ent = None
    for e in entities:
        if isinstance(e, dict) and e.get("id") == entity_id:
            ent = e
            break
    if ent is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Entity not found")
    if ent.get("status") != "active":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Entity not found")

    # ---- Compute content_hash (name+summary+observations snapshot)
    obs_texts = []
    for o in observations:
        if not isinstance(o, dict):
            continue
        if o.get("entity_id") != entity_id:
            continue
        if o.get("status") != "active":
            continue
        c = o.get("content")
        if isinstance(c, str) and c:
            obs_texts.append(c)
    obs_texts.sort()
    base = {
        "name": ent.get("name") if isinstance(ent.get("name"), str) else "",
        "summary": ent.get("summary") if isinstance(ent.get("summary"), str) else "",
        "observations": obs_texts,
    }
    content_hash = hashlib.sha256(json.dumps(base, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()

    # ---- Find or create embedding row
    emb = None
    for r in embeddings:
        if isinstance(r, dict) and r.get("entity_id") == entity_id and r.get("model") == model:
            emb = r
            break

    now_iso = _now_iso()

    if emb is None:
        emb = {
            "id": _new_id("mmt_emb_", embeddings),
            "entity_id": entity_id,
            "model": model,
            "dimensions": 1536,
            "vector": None,
            "content_hash": content_hash,
            "status": "queued",
            "last_error": None,
            "generated_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        embeddings.append(emb)
        # event
        ev = {
            "id": _new_id("mmt_evt_", graph_events),
            "event_type": "embedding.queued",
            "entity_id": entity_id,
            "relation_id": None,
            "observation_id": None,
            "embedding_id": emb["id"],
            "actor": {"tool": "force_generate_embedding"},
            "payload": {"embedding": dict(emb)},
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        graph_events.append(ev)
        _save("embeddings.json", embeddings)
        _save("graph_events.json", graph_events)
        _log("ok", None)
        return {
            "embedding": {k: emb.get(k) for k in emb.keys() if k != "vector"} | ({"vector": None} if emb.get("status") != "ready" else {"vector": emb.get("vector")}),
            "status": emb.get("status"),
        }

    # Idempotent-ish logic: queue if not ready, or if overwrite true, or if content hash changed
    should_queue = overwrite or (emb.get("status") != "ready") or (emb.get("content_hash") != content_hash)
    if not should_queue:
        _log("ok", None)
        return {
            "embedding": {k: emb.get(k) for k in emb.keys() if k != "vector"} | ({"vector": emb.get("vector")} if emb.get("status") == "ready" else {"vector": None}),
            "status": emb.get("status"),
        }

    # lifecycle transition: any -> queued is allowed only from ready/failed/missing; but schema allows ready->queued and failed->queued, missing->queued; queued->queued should be idempotent.
    cur = emb.get("status")
    if cur not in ("missing", "queued", "generating", "ready", "failed"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Embedding row has invalid status")
    # if generating, we still force set queued (service allows "queues or generates"; treat as force requeue)
    emb["status"] = "queued"
    emb["vector"] = None
    emb["generated_at"] = None
    emb["last_error"] = None
    emb["content_hash"] = content_hash
    emb["updated_at"] = now_iso

    ev = {
        "id": _new_id("mmt_evt_", graph_events),
        "event_type": "embedding.queued",
        "entity_id": entity_id,
        "relation_id": None,
        "observation_id": None,
        "embedding_id": emb.get("id"),
        "actor": {"tool": "force_generate_embedding"},
        "payload": {"embedding": dict(emb), "previous_status": cur, "overwrite": overwrite},
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    graph_events.append(ev)

    _save("embeddings.json", embeddings)
    _save("graph_events.json", graph_events)

    _log("ok", None)
    return {
        "embedding": {k: emb.get(k) for k in emb.keys() if k != "vector"} | ({"vector": None} if emb.get("status") != "ready" else {"vector": emb.get("vector")}),
        "status": emb.get("status"),
    }

def debug_embedding_config(entity_id=None, model=None, include_recent_events=None, events_limit=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": None,
            "endpoint": "debug_embedding_config",
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        logs = _load("request_logs.json")
        req["id"] = f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}"
        logs.append(req)
        _save("request_logs.json", logs)

    def _validate_ulid(prefix, s):
        if not isinstance(s, str):
            return False
        pat = r"^" + re.escape(prefix) + r"[0-9A-HJKMNP-TV-Z]{26}$"
        return re.match(pat, s) is not None

    # Validate
    if entity_id is not None:
        if not isinstance(entity_id, str) or not _validate_ulid("mmt_ent_", entity_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "entity_id must be a valid entity ULID")
    if model is not None and not isinstance(model, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model must be a string")
    if include_recent_events is None:
        include_recent_events = False
    if not isinstance(include_recent_events, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_recent_events must be a boolean")
    if events_limit is None:
        events_limit = 50
    if not isinstance(events_limit, int) or events_limit < 1 or events_limit > 500:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "events_limit must be between 1 and 500")

    embeddings = _load("embeddings.json")
    entities = _load("entities.json")
    graph_events = _load("graph_events.json")

    # Default model heuristic: most common in db else fixed
    counts = {}
    dims_by_model = {}
    for e in embeddings:
        if not isinstance(e, dict):
            continue
        m = e.get("model")
        if isinstance(m, str) and m:
            counts[m] = counts.get(m, 0) + 1
            d = e.get("dimensions")
            if isinstance(d, int) and d > 0:
                dims_by_model.setdefault(m, {})
                dims_by_model[m][d] = dims_by_model[m].get(d, 0) + 1
    default_model = (max(counts.items(), key=lambda kv: kv[1])[0] if counts else "text-embedding-3-small")
    if model is not None:
        model = model.strip()
        if model == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "model must be non-empty when provided")

    target_model = model or default_model

    # DB readiness: embeddings table presence = file load ok (we always load list), plus basic schema conformance count
    status_counts = {"missing": 0, "queued": 0, "generating": 0, "ready": 0, "failed": 0, "unknown": 0}
    total_for_model = 0
    ready_for_model = 0
    dims_counts = {}
    for e in embeddings:
        if not isinstance(e, dict):
            continue
        if e.get("model") != target_model:
            continue
        total_for_model += 1
        st = e.get("status")
        if st in status_counts:
            status_counts[st] += 1
        else:
            status_counts["unknown"] += 1
        if st == "ready":
            ready_for_model += 1
        d = e.get("dimensions")
        if isinstance(d, int):
            dims_counts[d] = dims_counts.get(d, 0) + 1

    # entity-specific output
    entity_embedding = None
    entity_exists = None
    if entity_id is not None:
        entity_exists = any(isinstance(en, dict) and en.get("id") == entity_id for en in entities)
        # return per-entity embedding status even if entity missing (diagnostic)
        for e in embeddings:
            if isinstance(e, dict) and e.get("entity_id") == entity_id and e.get("model") == target_model:
                entity_embedding = dict(e)
                if entity_embedding.get("status") != "ready":
                    entity_embedding["vector"] = None
                break

    # recent embedding events
    recent = None
    if include_recent_events:
        allowed = {"embedding.queued", "embedding.generated", "embedding.failed"}
        evs = [ev for ev in graph_events if isinstance(ev, dict) and ev.get("event_type") in allowed]
        if entity_id is not None:
            evs = [ev for ev in evs if ev.get("entity_id") == entity_id]
        if target_model is not None:
            # best-effort filter by embedding row's model if payload contains it
            def _match_model(ev):
                p = ev.get("payload") or {}
                emb = p.get("embedding") if isinstance(p, dict) else None
                if isinstance(emb, dict) and isinstance(emb.get("model"), str):
                    return emb.get("model") == target_model
                return True
            evs = [ev for ev in evs if _match_model(ev)]
        # sort by occurred_at desc then id desc
        def _key(ev):
            occ = ev.get("occurred_at")
            try:
                if isinstance(occ, str) and occ.endswith("Z"):
                    occ2 = occ[:-1] + "+00:00"
                else:
                    occ2 = occ
                dt = datetime.datetime.fromisoformat(occ2) if isinstance(occ2, str) else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (dt, ev.get("id") or "")
        evs.sort(key=_key, reverse=True)
        recent = evs[:events_limit]

    resp = {
        "embedding_config": {
            "default_model": default_model,
            "target_model": target_model,
            "default_dimensions_hint": (max(dims_counts.items(), key=lambda kv: kv[1])[0] if dims_counts else (1536 if target_model else None)),
        },
        "db_readiness": {
            "embeddings_table_present": True,
            "total_embeddings_for_target_model": total_for_model,
            "ready_embeddings_for_target_model": ready_for_model,
            "counts_by_status_for_target_model": status_counts,
            "dimensions_histogram_for_target_model": dims_counts,
        },
        "entity_debug": {
            "entity_id": entity_id,
            "entity_exists": entity_exists,
            "embedding_row": entity_embedding,
        } if entity_id is not None else None,
        "recent_embedding_events": recent,
    }

    _log("ok", None)
    return resp

def diagnose_vector_search(query, model=None, limit=None, min_score=None, include_vectors=None, include_missing=None, status=None, **_extra):
    import json, os, datetime, time, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_str, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        req = {
            "id": None,
            "endpoint": "diagnose_vector_search",
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        logs = _load("request_logs.json")
        req["id"] = f"mmt_req_{int(time.time()*1000)}_{len(logs)+1}"
        logs.append(req)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(query, str) or query.strip() == "":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if model is not None and not isinstance(model, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model must be a string")
    if limit is None:
        limit = 10
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if min_score is not None and not isinstance(min_score, (int, float)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min_score must be a number")
    if min_score is not None:
        min_score = float(min_score)
    if include_vectors is None:
        include_vectors = False
    if not isinstance(include_vectors, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_vectors must be a boolean")
    if include_missing is None:
        include_missing = False
    if not isinstance(include_missing, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_missing must be a boolean")
    allowed_status = {"missing", "queued", "generating", "ready", "failed"}
    if status is not None:
        if (not isinstance(status, list)) or any(not isinstance(s, str) for s in status):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be an array of strings")
        for s in status:
            if s not in allowed_status:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Invalid status value: {s}")

    embeddings = _load("embeddings.json")
    entities = _load("entities.json")

    # Default model heuristic: most common else fixed
    counts = {}
    for e in embeddings:
        if isinstance(e, dict) and isinstance(e.get("model"), str) and e.get("model"):
            counts[e["model"]] = counts.get(e["model"], 0) + 1
    default_model = (max(counts.items(), key=lambda kv: kv[1])[0] if counts else "text-embedding-3-small")
    target_model = (model.strip() if isinstance(model, str) and model.strip() else default_model)

    ent_name = {}
    ent_status = {}
    for en in entities:
        if isinstance(en, dict) and en.get("id"):
            ent_name[en["id"]] = en.get("name")
            ent_status[en["id"]] = en.get("status")

    # Candidate embeddings
    candidates = []
    missing = []
    for emb in embeddings:
        if not isinstance(emb, dict):
            continue
        if emb.get("model") != target_model:
            continue
        eid = emb.get("entity_id")
        if not eid:
            continue
        st = emb.get("status")
        if status is not None and st not in set(status):
            continue
        if st != "ready":
            if include_missing:
                missing.append({
                    "entity_id": eid,
                    "entity_name": ent_name.get(eid),
                    "entity_status": ent_status.get(eid),
                    "embedding_id": emb.get("id"),
                    "embedding_status": st,
                    "last_error": emb.get("last_error"),
                })
            continue
        vec = emb.get("vector")
        if not isinstance(vec, list) or not vec or any(not isinstance(x, (int, float)) for x in vec):
            # treat as not usable
            if include_missing:
                missing.append({
                    "entity_id": eid,
                    "entity_name": ent_name.get(eid),
                    "entity_status": ent_status.get(eid),
                    "embedding_id": emb.get("id"),
                    "embedding_status": "failed",
                    "last_error": "Invalid or missing vector despite status='ready'",
                })
            continue
        candidates.append((emb, vec))

    # If no vectors, return empty results
    if not candidates:
        resp = {
            "model": target_model,
            "query": query,
            "limit": limit,
            "min_score": min_score,
            "candidates_considered": 0,
            "results": [],
            "missing_embeddings": missing if include_missing else None,
            "note": "No ready embeddings available for the requested model" if not embeddings else None,
        }
        _log("ok", None)
        return resp

    # Build a deterministic, lightweight query embedding (hash->unit vector) with same dims as candidates[0]
    dim = len(candidates[0][1])
    import hashlib
    h = hashlib.sha256(query.strip().encode("utf-8")).digest()
    # expand bytes to dim floats
    q = []
    for i in range(dim):
        b = h[i % len(h)]
        q.append((b / 255.0) * 2.0 - 1.0)
    # normalize
    qn = math.sqrt(sum(x * x for x in q)) or 1.0
    q = [x / qn for x in q]

    def _cos(a, b):
        # assume same length
        dot = 0.0
        na = 0.0
        nb = 0.0
        for i in range(len(a)):
            x = float(a[i])
            y = float(b[i])
            dot += x * y
            na += x * x
            nb += y * y
        denom = (math.sqrt(na) * math.sqrt(nb)) or 1.0
        return dot / denom

    scored = []
    for emb, vec in candidates:
        if len(vec) != dim:
            continue
        s = _cos(q, vec)
        if min_score is not None and s + 1e-12 < min_score:
            continue
        scored.append((s, emb, vec))

    scored.sort(key=lambda t: (t[0], t[1].get("id") or ""), reverse=True)
    top = scored[:limit]

    results = []
    for s, emb, vec in top:
        row = {
            "entity_id": emb.get("entity_id"),
            "entity_name": ent_name.get(emb.get("entity_id")),
            "entity_status": ent_status.get(emb.get("entity_id")),
            "embedding_id": emb.get("id"),
            "embedding_status": emb.get("status"),
            "score": s,
            "dimensions": emb.get("dimensions"),
        }
        if include_vectors:
            row["vector"] = vec
        results.append(row)

    resp = {
        "model": target_model,
        "query": query,
        "limit": limit,
        "min_score": min_score,
        "dimensions": dim,
        "candidates_considered": len(candidates),
        "results": results,
        "missing_embeddings": missing if include_missing else None,
        "method": "cosine_similarity(hash_embedding(query), stored_embedding.vector)",
        "warning": "Diagnostic-only query embedding (deterministic hash) used; not representative of production model embeddings.",
    }

    _log("ok", None)
    return resp

def list_entities(query=None, entity_type=None, status=None, include_deleted=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _log(endpoint, status_code, message=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": latency_ms,
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        if isinstance(extra, dict):
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limiting / quota (best-effort; only if config exists)
    def _enforce_limits(endpoint):
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limits") if isinstance(cfg.get("rate_limits"), dict) else None
            if rl and isinstance(rl.get("per_minute"), int) and rl["per_minute"] > 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    return None
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
                c = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    dt = _parse_dt(r.get("occurred_at"))
                    if dt and dt >= cutoff:
                        c += 1
                if c >= rl["per_minute"]:
                    return _err("RATE_LIMIT", "Rate limit exceeded", limit=rl["per_minute"], window_seconds=60)
            quota = cfg.get("quotas") if isinstance(cfg.get("quotas"), dict) else None
            if quota and isinstance(quota.get("reads_per_day"), int) and quota["reads_per_day"] > 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    return None
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
                c = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if not isinstance(r.get("endpoint"), str):
                        continue
                    if not r["endpoint"].startswith("list_entities") and not r["endpoint"].startswith("get_entity"):
                        continue
                    dt = _parse_dt(r.get("occurred_at"))
                    if dt and dt >= cutoff:
                        c += 1
                if c >= quota["reads_per_day"]:
                    return _err("QUOTA_EXCEEDED", "Read quota exceeded", quota=quota["reads_per_day"], window_seconds=86400)
        return None

    lim_err = _enforce_limits("list_entities")
    if lim_err:
        _log("list_entities", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    # Validate inputs
    if query is not None and not isinstance(query, str):
        e = _err("VALIDATION_ERROR", "query must be a string")
        _log("list_entities", e["error"]["code"], e["error"]["message"])
        return e
    if entity_type is not None and not isinstance(entity_type, str):
        e = _err("VALIDATION_ERROR", "entity_type must be a string")
        _log("list_entities", e["error"]["code"], e["error"]["message"])
        return e
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        e = _err("VALIDATION_ERROR", "include_deleted must be a boolean")
        _log("list_entities", e["error"]["code"], e["error"]["message"])
        return e
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            e = _err("VALIDATION_ERROR", "status must be one of: active, deleted")
            _log("list_entities", e["error"]["code"], e["error"]["message"])
            return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        _log("list_entities", e["error"]["code"], e["error"]["message"])
        return e
    if sort is None:
        sort = "updated_at_desc"
    if not isinstance(sort, str) or sort not in ("updated_at_desc", "created_at_desc", "name_asc"):
        e = _err("VALIDATION_ERROR", "sort must be one of: updated_at_desc, created_at_desc, name_asc")
        _log("list_entities", e["error"]["code"], e["error"]["message"])
        return e
    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string")
        _log("list_entities", e["error"]["code"], e["error"]["message"])
        return e

    # Determine effective status filter
    if status is None:
        if include_deleted:
            status_filter = None  # include both
        else:
            status_filter = "active"
    else:
        status_filter = status
        if status_filter == "deleted" and not include_deleted:
            # caller asked for deleted but did not opt in
            e = _err("VALIDATION_ERROR", "include_deleted=true is required to list deleted entities")
            _log("list_entities", e["error"]["code"], e["error"]["message"])
            return e

    ents = _load("entities.json")
    if not isinstance(ents, list):
        ents = []

    q = query.strip().lower() if isinstance(query, str) and query.strip() != "" else None
    et = entity_type if isinstance(entity_type, str) and entity_type != "" else entity_type  # allow empty string match? treat literally
    out = []
    for r in ents:
        if not isinstance(r, dict):
            continue
        st = r.get("status")
        if status_filter is not None and st != status_filter:
            continue
        if not include_deleted and st == "deleted":
            continue
        if et is not None and r.get("entity_type") != et:
            continue
        if q is not None:
            nm = r.get("name")
            if not isinstance(nm, str) or q not in nm.lower():
                continue
        out.append(r)

    def _dt_or_min(s):
        dt = _parse_dt(s)
        if dt is None:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    if sort == "updated_at_desc":
        out.sort(key=lambda r: (_dt_or_min(r.get("updated_at")), str(r.get("id") or "")), reverse=True)
    elif sort == "created_at_desc":
        out.sort(key=lambda r: (_dt_or_min(r.get("created_at")), str(r.get("id") or "")), reverse=True)
    else:  # name_asc
        out.sort(key=lambda r: ((str(r.get("name") or "").lower()), str(r.get("id") or "")))

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                raise ValueError("bad cursor version")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("negative")
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor")
            _log("list_entities", e["error"]["code"], e["error"]["message"])
            return e

    total = len(out)
    page = out[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"v1:{start+limit}".encode("utf-8")).decode("utf-8")

    resp = {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
    _log("list_entities", "OK", extra={"returned": len(page), "total": total})
    return resp

