def update_entity(entity_id, name=None, entity_type=None, summary=None, properties=None, confidence=None, confidence_updated_at=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0105000" if __import__("os").path.isdir("./environment_mix/0105000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status_code,
            "message": message,
            "latency_ms": latency_ms,
            "occurred_at": now,
            "created_at": now,
            "updated_at": now
        }
        if isinstance(extra, dict):
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limits") if isinstance(cfg.get("rate_limits"), dict) else None
            if rl and isinstance(rl.get("writes_per_minute"), int) and rl["writes_per_minute"] > 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    return None
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
                c = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    dt = _parse_dt(r.get("occurred_at"))
                    if dt and dt >= cutoff:
                        c += 1
                if c >= rl["writes_per_minute"]:
                    return _err("RATE_LIMIT", "Rate limit exceeded", limit=rl["writes_per_minute"], window_seconds=60)
            quota = cfg.get("quotas") if isinstance(cfg.get("quotas"), dict) else None
            if quota and isinstance(quota.get("writes_per_day"), int) and quota["writes_per_day"] > 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    return None
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
                c = 0
                for r in logs:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    dt = _parse_dt(r.get("occurred_at"))
                    if dt and dt >= cutoff:
                        c += 1
                if c >= quota["writes_per_day"]:
                    return _err("QUOTA_EXCEEDED", "Write quota exceeded", quota=quota["writes_per_day"], window_seconds=86400)
        return None

    lim_err = _enforce_limits("update_entity")
    if lim_err:
        _log("update_entity", lim_err["error"]["code"], lim_err["error"]["message"])
        return lim_err

    # Validate inputs
    if not isinstance(entity_id, str):
        e = _err("VALIDATION_ERROR", "entity_id must be a string")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e
    if not re.match(r"^mmt_ent_[0-9A-HJKMNP-TV-Z]{10,}$", entity_id):
        e = _err("VALIDATION_ERROR", "Invalid entity_id format")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e

    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        e = _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e
    if entity_type is not None and not isinstance(entity_type, str):
        e = _err("VALIDATION_ERROR", "entity_type must be a string")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e
    if summary is not None and not isinstance(summary, str):
        e = _err("VALIDATION_ERROR", "summary must be a string")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e
    if properties is not None and not isinstance(properties, dict):
        e = _err("VALIDATION_ERROR", "properties must be an object")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e
    if confidence is not None:
        if not isinstance(confidence, (int, float)):
            e = _err("VALIDATION_ERROR", "confidence must be a number")
            _log("update_entity", e["error"]["code"], e["error"]["message"])
            return e
        if confidence < 0 or confidence > 1:
            e = _err("VALIDATION_ERROR", "confidence must be between 0.0 and 1.0")
            _log("update_entity", e["error"]["code"], e["error"]["message"])
            return e
        confidence = float(confidence)

    cudt = None
    if confidence_updated_at is not None:
        cudt = _parse_dt(confidence_updated_at)
        if cudt is None:
            e = _err("VALIDATION_ERROR", "confidence_updated_at must be an RFC3339 datetime string")
            _log("update_entity", e["error"]["code"], e["error"]["message"])
            return e

    ents = _load("entities.json")
    if not isinstance(ents, list):
        ents = []

    idx = None
    current = None
    for i, r in enumerate(ents):
        if isinstance(r, dict) and r.get("id") == entity_id:
            idx = i
            current = r
            break

    if current is None:
        e = _err("NOT_FOUND", "Entity not found", entity_id=entity_id)
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e

    if current.get("status") == "deleted":
        e = _err("CONFLICT", "Entity is deleted and cannot be updated", entity_id=entity_id)
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e

    # Enforce unique(lower(name)) among active if changing name
    new_name = current.get("name")
    if name is not None:
        new_name = name.strip()
        target_lower = new_name.lower()
        for r in ents:
            if not isinstance(r, dict):
                continue
            if r.get("id") == entity_id:
                continue
            if r.get("status") != "active":
                continue
            nm = r.get("name")
            if isinstance(nm, str) and nm.lower() == target_lower:
                e = _err("CONFLICT", "An active entity with this name already exists", name=new_name)
                _log("update_entity", e["error"]["code"], e["error"]["message"])
                return e

    before = dict(current)

    # Apply updates
    changed = False
    if name is not None and new_name != current.get("name"):
        current["name"] = new_name
        changed = True
    if entity_type is not None and entity_type != current.get("entity_type"):
        current["entity_type"] = entity_type
        changed = True
    if summary is not None and summary != current.get("summary"):
        current["summary"] = summary
        changed = True
    if properties is not None and properties != current.get("properties"):
        current["properties"] = properties
        changed = True
    if confidence is not None and confidence != current.get("confidence"):
        current["confidence"] = confidence
        # server sets confidence_updated_at to provided or now
        current["confidence_updated_at"] = _iso(cudt) if cudt is not None else now
        changed = True
    elif confidence is None and confidence_updated_at is not None:
        # confidence_updated_at without confidence doesn't make sense: reject
        e = _err("VALIDATION_ERROR", "confidence_updated_at requires confidence to be set")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e

    # Maintain constraints: deleted_at null when active
    current["status"] = "active"
    current["deleted_at"] = None

    if not changed:
        # No mutation => treat as NOT_FOUND? No; entity exists. But contract says no success without effect for mutations.
        e = _err("VALIDATION_ERROR", "No updatable fields provided or no changes detected")
        _log("update_entity", e["error"]["code"], e["error"]["message"])
        return e

    current["updated_at"] = now
    ents[idx] = current
    _save("entities.json", ents)

    # Emit graph event entity.updated with before/after snapshot
    events = _load("graph_events.json")
    if not isinstance(events, list):
        events = []
    ev_id = "mmt_evt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    ev = {
        "id": ev_id,
        "event_type": "entity.updated",
        "entity_id": entity_id,
        "relation_id": None,
        "observation_id": None,
        "embedding_id": None,
        "actor": {"tool": "update_entity"},
        "payload": {"before": before, "after": dict(current)},
        "occurred_at": now,
        "created_at": now,
        "updated_at": now
    }
    events.append(ev)
    _save("graph_events.json", events)

    resp = {"object": "entity", "data": current}
    _log("update_entity", "OK", extra={"entity_id": entity_id})
    return resp
